   "orig": "La missione come incontro di un amore che cambia la vita",
   "lead": "Nel centenario della Giornata missionaria mondiale, padre Gandolfi racconta dal Sud Sudan la sua esperienza di missione. Secondo il sacerdote, la missione inizia quando si smette di considerare le persone come destinatarie di un servizio e si comincia a guardarle negli occhi. I poveri, afferma, hanno un nome. Lo riferisce Vatican News.",
