   "titolo": "Intelligenza artificiale, clima e capitali privati: le fortune divergenti dell'Asia",
   "orig": "AI, climate and private capital reveal Asia's diverging fortunes",
   "lead": "Intelligenza artificiale, cambiamento climatico e capitali privati sono tre fattori che stanno facendo emergere destini sempre più diversi tra le economie asiatiche. L'analisi esamina come queste forze stiano ridisegnando gli equilibri del continente. Alcuni Paesi ne traggono vantaggio, mentre altri rischiano di restare indietro. Il quadro che ne risulta è quello di un'Asia meno omogenea, in cui le traiettorie di crescita si separano. Lo riferisce Nikkei Asia.",
